mapper.insert:
INSERT INTO mall_seckill_order (
    id, order_id, order_no, user_id, activity_id, product_id, sku_id,
    product_name, product_image, spec_desc, seckill_price, quantity, request_id
) VALUES (
    #{id}, #{orderId}, #{orderNo}, #{userId}, #{activityId}, #{productId}, #{skuId},
    #{productName}, #{productImage}, #{specDesc}, #{seckillPrice}, #{quantity}, #{requestId}
)

mapper.select:
SELECT SUM(so.quantity)
FROM mall_seckill_order so
JOIN mall_order o ON o.id = so.order_id
WHERE so.activity_id = #{activityId}
  AND so.user_id = #{userId}
  AND o.status != 'CANCELLED'
